const links = new Map();
const hits = new Map();

const ALPHABET = 'abcdefghijklmnopqrstuvwxyz0123456789';
const CODE_LENGTH = 6;
const MAX_URL_LENGTH = 2048;
const MAX_HITS_PER_CODE = 5000;

export function createCode() {
  let code = '';
  for (let i = 0; i < CODE_LENGTH; i++) {
    code += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
  }
  return code;
}

/** Throws on anything that is not a plausible http(s) URL. */
export function validateUrl(value) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error('url must be a non-empty string');
  }
  if (value.length > MAX_URL_LENGTH) {
    throw new Error(`url must be at most ${MAX_URL_LENGTH} characters`);
  }
  let parsed;
  try {
    parsed = new URL(value);
  } catch {
    throw new Error('url is not a valid URL');
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new Error('url must use http or https');
  }
  return parsed.toString();
}

export function shorten(url, label) {
  const normalised = validateUrl(url);

  // Retry on collision rather than silently overwriting someone else's link.
  let code = createCode();
  for (let attempt = 0; links.has(code) && attempt < 10; attempt++) code = createCode();
  if (links.has(code)) throw new Error('could not allocate a unique code');

  links.set(code, {
    code,
    url: normalised,
    label: typeof label === 'string' && label.trim() ? label.trim().slice(0, 40) : normalised,
    createdAt: Date.now(),
  });
  hits.set(code, []);
  return code;
}

export function resolve(code) {
  if (typeof code !== 'string') return undefined;
  return links.get(code)?.url;
}

/**
 * Record one click.
 *
 * Increment-in-place on the array we already hold. Nothing reads a count,
 * computes a new one and writes it back, so a burst of clicks arriving together
 * cannot lose any of them.
 */
export function recordHit(code, referrer) {
  const entries = hits.get(code);
  if (!entries) return false;
  if (entries.length >= MAX_HITS_PER_CODE) entries.shift();
  entries.push({ at: Date.now(), referrer: referrer ?? null });
  return true;
}

export function stats(code) {
  const link = links.get(code);
  const entries = hits.get(code);
  if (!link || !entries) return null;
  return {
    code,
    url: link.url,
    label: link.label,
    clicks: entries.length,
    lastClickAt: entries.length ? entries[entries.length - 1].at : null,
    referrers: entries.reduce((acc, hit) => {
      const key = hit.referrer ?? 'direct';
      acc[key] = (acc[key] ?? 0) + 1;
      return acc;
    }, {}),
  };
}

/** Every link, busiest first — exactly what the dashboard chart renders. */
export function allStats() {
  return [...links.keys()]
    .map((code) => stats(code))
    .filter(Boolean)
    .sort((a, b) => b.clicks - a.clicks || a.code.localeCompare(b.code));
}

export function totalClicks() {
  let total = 0;
  for (const entries of hits.values()) total += entries.length;
  return total;
}

/** Clicks per second over the last `seconds`, oldest bucket first. */
export function clicksPerSecond(seconds = 30, now = Date.now()) {
  const buckets = new Array(seconds).fill(0);
  for (const entries of hits.values()) {
    for (const hit of entries) {
      const age = Math.floor((now - hit.at) / 1000);
      if (age >= 0 && age < seconds) buckets[seconds - 1 - age] += 1;
    }
  }
  return buckets;
}

export function reset() {
  links.clear();
  hits.clear();
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shorten, resolve, recordHit, stats, allStats, totalClicks, clicksPerSecond, validateUrl, reset } from './store.js';

test('shortens and resolves a url', () => {
  reset();
  const code = shorten('https://example.com');
  assert.equal(resolve(code), 'https://example.com/');
});

test('rejects input that is not a usable url', () => {
  reset();
  assert.throws(() => shorten(''), /non-empty/);
  assert.throws(() => shorten(null), /non-empty/);
  assert.throws(() => shorten('not a url'), /valid URL/);
  assert.throws(() => shorten('ftp://example.com'), /http or https/);
  assert.throws(() => shorten('https://example.com/' + 'x'.repeat(3000)), /at most/);
});

test('validateUrl normalises rather than echoing input', () => {
  assert.equal(validateUrl('https://EXAMPLE.com'), 'https://example.com/');
});

test('resolve returns undefined for an unknown code', () => {
  reset();
  assert.equal(resolve('nope42'), undefined);
  assert.equal(resolve(undefined), undefined);
});

test('counts clicks and attributes referrers', () => {
  reset();
  const code = shorten('https://example.com');
  recordHit(code, 'https://news.example');
  recordHit(code, null);
  const s = stats(code);
  assert.equal(s.clicks, 2);
  assert.equal(s.referrers['https://news.example'], 1);
  assert.equal(s.referrers.direct, 1);
});

test('a burst of clicks loses none of them', () => {
  reset();
  const code = shorten('https://example.com');
  for (let i = 0; i < 500; i++) recordHit(code, null);
  assert.equal(stats(code).clicks, 500);
  assert.equal(totalClicks(), 500);
});

test('recording a hit on an unknown code fails softly', () => {
  reset();
  assert.equal(recordHit('nope42', 'x'), false);
});

test('stats for an unknown code is null, not a crash', () => {
  reset();
  assert.equal(stats('nope42'), null);
});

test('allStats ranks busiest first, which is what the chart draws', () => {
  reset();
  const quiet = shorten('https://quiet.example', 'quiet');
  const busy = shorten('https://busy.example', 'busy');
  for (let i = 0; i < 5; i++) recordHit(busy, null);
  recordHit(quiet, null);
  const ranked = allStats();
  assert.equal(ranked[0].code, busy);
  assert.equal(ranked[0].clicks, 5);
  assert.equal(ranked[1].code, quiet);
});

test('clicksPerSecond buckets recent clicks and ignores old ones', () => {
  reset();
  const code = shorten('https://example.com');
  recordHit(code, null);
  const buckets = clicksPerSecond(30);
  assert.equal(buckets.length, 30);
  assert.equal(buckets.reduce((a, b) => a + b, 0), 1);
  assert.equal(buckets[29], 1, 'newest click belongs in the newest bucket');
  // A click from an hour ago must not appear in a 30 second window.
  assert.equal(clicksPerSecond(30, Date.now() + 3_600_000).reduce((a, b) => a + b, 0), 0);
});

